{
  "steps": [
    {
      "action": "Inventory the target binary's format, architecture, entrypoints, sections, imports, exports, symbols, strings, and protections, and record any analysis blockers that would impede static analysis of input-validation logic.",
      "technique": "RE-BINARY-INVENTORY",
      "deterministic_check": "The analyzed artifact hash matches campaign metadata; binary format and architecture are recorded; inventory artifacts (section table, import/export lists, symbol table, string extraction) exist and parse successfully; missing or malformed inputs are reported as incomplete rather than absence."
    },
    {
      "action": "Build a static call graph around the identified input surface(s), enumerating entrypoints, callers, callees, and unresolved indirect calls that may participate in input handling and validation.",
      "technique": "RE-STATIC-CALLGRAPH",
      "deterministic_check": "Every claimed call edge has an address or symbol locator; unresolved indirect calls are listed explicitly; the call graph distinguishes proven paths from candidate paths."
    },
    {
      "action": "Trace input acquisition through parsing, transformations, comparisons, and branch decisions to recover the validation logic, documenting both success and rejection paths with decompilation or disassembly evidence, and representing unknown helper behavior as unresolved dependencies.",
      "technique": "RE-INPUT-VALIDATION-TRACE",
      "deterministic_check": "The input source and destination representation are identified; every success and rejection branch has a code locator; transformations and comparison constants are supported by decompilation or disassembly evidence; unknown helper behavior is represented as an unresolved dependency."
    }
  ]
}
